<template>
  <view class="sos-page">
    <AppHeader />
    <PageContainer wide>
      <view class="sos-hero">
        <section class="safety-panel">
          <view class="safety-orb"><text>盾</text></view>
          <text class="eyebrow">TRAVELING SAFETY DESK</text>
          <text class="hero-title">需要帮助时<br />我们就在这里</text>
          <text class="hero-copy">紧急情况请优先直接拨打景区服务热线。非紧急求助可在此提交电子工单，景区指挥中心管理后台将即时接收处理。</text>
          <view class="emergency-button" role="button" @tap="emergencyOpen = true"><text>☎</text><text>紧急情况拨打 110 / 120 / 119</text></view>
          <view class="safety-note"><text class="note-dot" />{{ cityName }} · 旅灵安全支持中心</view>
        </section>
        <section class="form-card">
          <view class="form-heading"><view><text class="form-kicker">SOS REQUEST</text><text class="form-title">请填写求助信息</text></view><text class="form-status">SECURE FORM</text></view>
          <view class="form-grid">
            <label class="field"><text>求助类型 <em>*</em></text><picker :range="helpOptions" range-key="label" @change="changeHelpType"><view class="select">{{ selectedHelp.label }}<text>⌄</text></view></picker></label>
            <view class="urgency-field"><text>紧急程度</text><view class="urgency-options"><view v-for="item in urgencyOptions" :key="item.value" class="urgency" :class="{ active: form.urgency === item.value }" @tap="form.urgency = item.value"><text>{{ item.label }}</text></view></view></view>
            <label class="field field-wide"><text>当前所在位置 <em>*</em></text><view class="location-row"><input v-model="form.locationText" placeholder="例如：灵隐大佛堂云连中段" /><button class="locate-button" :disabled="locating" @tap="locate">{{ locating ? '定位中' : '定位' }}</button></view><text v-if="locationMessage" class="field-hint">{{ locationMessage }}</text></label>
            <label class="field field-wide"><text>您的联系电话 <em>*</em></text><input v-model="form.phone" type="tel" maxlength="24" placeholder="请输入手机号，便于工作人员及时联系您" /></label>
            <label class="field field-wide"><text>现场具体情况说明 <em>*</em></text><textarea v-model="form.description" maxlength="2000" placeholder="请详细描述遇到的问题、需要的帮助类型，以便我们更快速地为您提供支援……" /></label>
          </view>
          <view v-if="riskNotice" class="risk-notice">⚠ {{ riskNotice }}</view>
          <button class="submit-button" :disabled="submitting" @tap="submit">{{ submitting ? '正在创建工单…' : '立即创建求助工单' }}<text>→</text></button>
          <text class="privacy-note">信息仅用于景区求助处理，我们不会公开您的联系方式。</text>
        </section>
      </view>
    </PageContainer>
    <view v-if="emergencyOpen" class="modal-mask" @tap.self="emergencyOpen = false"><view class="emergency-modal"><view class="modal-head"><text>紧急联系电话</text><text class="close" @tap="emergencyOpen = false">×</text></view><text class="modal-copy">如存在即时人身安全风险，请优先拨打对应公共服务电话。</text><view v-for="item in emergencyContacts" :key="item.number" class="contact-row" @tap="call(item.number)"><view><text class="contact-name">{{ item.name }}</text><text class="contact-desc">{{ item.desc }}</text></view><text class="contact-number">{{ item.number }} ›</text></view></view></view>
    <view v-if="created" class="success-panel"><view class="success-icon">✓</view><text class="success-title">求助工单已创建</text><text class="ticket-no">{{ created.requestNo }}</text><view class="success-grid"><text>状态</text><text>等待景区工作人员响应</text><text>提交时间</text><text>{{ formatTime(created.createdAt) }}</text><text>当前位置</text><text>{{ created.locationText }}</text></view><view class="success-actions"><button @tap="viewStatus">查看工单状态</button><button @tap="goHome">返回首页</button></view></view>
  </view>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import AppHeader from '../../components/layout/AppHeader.vue';
import PageContainer from '../../components/layout/PageContainer.vue';
import { initializeCityContext } from '../../composables/useCityContext';
import { useTouristStore } from '../../stores';
import { post, get } from '../../utils/request';
import type { SosRequestVO } from '../../types';
type Option = { label: string; value: string };
const store = useTouristStore();
const cityName = computed(() => store.currentCity?.cityName || '当前景区');
const helpOptions: Option[] = [{ label: '迷路 / 找不到路线', value: 'LOST' }, { label: '身体不适', value: 'MEDICAL' }, { label: '物品遗失', value: 'ITEM_LOST' }, { label: '景区设施问题', value: 'FACILITY' }, { label: '交通问题', value: 'TRAFFIC' }, { label: '安全问题', value: 'SAFETY' }, { label: '老人/儿童走失', value: 'MISSING_PERSON' }, { label: '其他', value: 'OTHER' }];
const urgencyOptions: Option[] = [{ label: '普通', value: 'NORMAL' }, { label: '较急', value: 'URGENT' }, { label: '紧急', value: 'EMERGENCY' }];
const emergencyContacts = [{ name: '公安报警', number: '110', desc: '人身安全、治安事件' }, { name: '医疗急救', number: '120', desc: '突发疾病、医疗救助' }, { name: '消防救援', number: '119', desc: '火灾、危险救援' }];
const form = reactive({ helpType: 'LOST', urgency: 'NORMAL', locationText: '', phone: '', description: '', longitude: null as number | null, latitude: null as number | null });
const emergencyOpen = ref(false); const locating = ref(false); const submitting = ref(false); const locationMessage = ref(''); const created = ref<SosRequestVO | null>(null);
const selectedHelp = computed(() => helpOptions.find(item => item.value === form.helpType) || helpOptions[0]);
const riskNotice = computed(() => ['MEDICAL', 'SAFETY', 'MISSING_PERSON'].includes(form.helpType) ? '如果存在即时人身安全风险，请优先拨打 110 / 120 / 119。' : '');
function changeHelpType(event: { detail: { value: number } }): void { form.helpType = helpOptions[event.detail.value]?.value || 'OTHER'; }
function call(number: string): void { uni.makePhoneCall({ phoneNumber: number }); }
function locate(): void { locating.value = true; locationMessage.value = ''; uni.getLocation({ type: 'gcj02', success: ({ longitude, latitude }) => { form.longitude = longitude; form.latitude = latitude; form.locationText = `当前位置（经度 ${longitude.toFixed(5)}，纬度 ${latitude.toFixed(5)}）`; locationMessage.value = '已获取当前位置，也可以继续补充地标。'; }, fail: () => { locationMessage.value = '暂时无法获取定位，请手动填写位置，不影响提交。'; }, complete: () => { locating.value = false; } }); }
async function submit(): Promise<void> { if (!form.locationText.trim() || !form.phone.trim() || !form.description.trim()) { uni.showToast({ title: '请补充必填信息', icon: 'none' }); return; } submitting.value = true; try { created.value = await post<SosRequestVO>('/api/tourist/sos', { ...form, cityId: store.currentCity?.id || null }); } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '工单创建失败', icon: 'none' }); } finally { submitting.value = false; } }
async function viewStatus(): Promise<void> { if (!created.value) return; try { created.value = await get<SosRequestVO>(`/api/tourist/sos/${created.value.requestNo}`); uni.showToast({ title: `当前状态：${created.value.status}`, icon: 'none' }); } catch { uni.showToast({ title: '暂时无法查询工单', icon: 'none' }); } }
function formatTime(value?: string | null): string { return value ? value.replace('T', ' ').slice(0, 16) : '刚刚'; }
function goHome(): void { uni.reLaunch({ url: '/pages/index/index' }); }
onMounted(() => { void initializeCityContext().catch(() => undefined); });
</script>

