adding:15px 0;border-top:1px solid #e2eee8}.contact-row text{display:block}.contact-name{font-weight:800}.contact-desc{margin-top:4px;color:#81968e;font-size:12px}.contact-number{color:#138d78;font-size:20px;font-weight:800}.success-panel{position:fixed;z-index:20;right:24px;bottom:24px;width:min(430px,calc(100vw - 32px));padding:26px;color:#173f35;background:rgba(248,255,251,.98);border:1px solid #bfe9d9;border-radius:20px;box-shadow:0 20px 60px rgba(0,0,0,.28);box-sizing:border-box}.success-icon{display:grid;place-items:center;width:42px;height:42px;color:white;background:#1aa081;border-radius:50%;font-size:24px}.success-title{display:block;margin-top:13px;font-size:22px;font-weight:800}.ticket-no{display:block;margin-top:5px;color:#148b77;font-size:13px;font-weight:800}.success-grid{display:grid;grid-template-columns:80px 1fr;gap:10px 14px;margin-top:20px;font-size:12px}.success-grid text:nth-child(odd){color:#8aa098}.success-actions{display:flex;gap:10px;margin-top:22px}.success-actions button{flex:1;margin:0;color:#137e6d;background:#e1f6ef;border:0;border-radius:10px;font-size:12px}@media(max-width:900px){.sos-hero{grid-template-columns:1fr;min-height:auto;padding:44px 3vw}.safety-panel{max-width:none}}@media(max-width:600px){.sos-page{padding-top:8px}.sos-hero{gap:30px;padding:30px 0}.hero-title{font-size:42px}.hero-copy{font-size:14px}.emergency-button{width:100%;justify-content:center;box-sizing:border-box;font-size:13px}.form-card{padding:22px 17px;border-radius:20px}.form-status{display:none}.form-grid{grid-template-columns:1fr}.field-wide{grid-column:auto}.location-row{display:grid;grid-template-columns:1fr auto}.success-panel{right:16px;bottom:16px}.success-actions{flex-direction:column}}
</style>
